package com.braseiro.dnd5e;

import org.json.JSONArray;
import org.json.JSONObject;
import java.text.Normalizer;
import java.util.*;

/** RUN134 — 15 talentos raciais de Xanathar, com escolhas e rolagens explícitas. */
public final class XanatharRacialFeatRuntimeEngine {
    public static final String SOURCE="Xanathar's Guide to Everything";
    private static final String[] FEATS={"Agachamento Ágil","Alta Magia Drow","Boa Sorte","Chamas de Phlegethos","Constituição Infernal","Couro de Dragão","Desvanecer","Fortitude Anã","Fúria Orc","Magia do Elfo da Floresta","Precisão Élfica","Prodígio","Segunda Chance","Teleporte das Fadas","Temor Dracônico"};
    private XanatharRacialFeatRuntimeEngine(){}
    public static JSONArray allFeats(){JSONArray a=new JSONArray();for(String f:FEATS)a.put(f);return a;}
    public static boolean isKnownFeat(String f){String n=norm(f);for(String x:FEATS)if(norm(x).equals(n))return true;return false;}

    /** Lista somente talentos cujo pré-requisito racial é demonstrável; sub-raças exigem lineage explícita. */
    public static JSONArray eligibleFeats(String species,String lineage,String size){JSONArray a=new JSONArray();String s=baseSpecies(species),l=norm(lineage);boolean small=norm(size).contains("pequeno")||s.contains("gnomo")||s.contains("halfling")||s.contains("kobold")||s.contains("goblin");
        if(s.contains("anao")||small)a.put("Agachamento Ágil");
        if(s.contains("anao"))a.put("Fortitude Anã");
        if(s.contains("draconato")){a.put("Couro de Dragão");a.put("Temor Dracônico");}
        if(s.contains("elfo")||s.contains("meio elfo"))a.put("Precisão Élfica");
        if(s.contains("elfo")&&l.contains("alto"))a.put("Teleporte das Fadas");
        if(s.contains("elfo")&&l.contains("drow"))a.put("Alta Magia Drow");
        if(s.contains("elfo")&&(l.contains("floresta")||l.contains("silvestre")))a.put("Magia do Elfo da Floresta");
        if(s.contains("gnomo"))a.put("Desvanecer");
        if(s.contains("halfling")){a.put("Boa Sorte");a.put("Segunda Chance");}
        if(s.equals("humano")||s.contains("meio elfo")||s.contains("meio orc"))a.put("Prodígio");
        if(s.contains("meio orc"))a.put("Fúria Orc");
        if(s.contains("tiefling")){a.put("Chamas de Phlegethos");a.put("Constituição Infernal");}
        return a;
    }

    public static JSONObject applyFeat(JSONObject o,String feat,JSONObject choices){JSONObject r=new JSONObject();try{if(o==null||!isKnownFeat(feat))return r.put("ok",false).put("reason","unknown_feat");JSONObject c=choices==null?new JSONObject():choices;String f=norm(feat),species=baseSpecies(o.optString("species")),lineage=norm(c.optString("lineage",o.optString("species_lineage"))),size=norm(c.optString("size",o.optString("size",o.optString("size_options"))));if(!eligible(feat,species,lineage,size))return r.put("ok",false).put("reason","prerequisite_not_met");if(alreadyApplied(o,feat))return r.put("ok",true).put("feat",feat).put("already_applied",true);
        if(f.equals("agachamento agil")){String ab=requireAbility(c,"Força|Destreza");if(ab==null)return need(r,"ability");addAbility(o,ab,1);String sk=c.optString("skill");if(!(norm(sk).equals("acrobacia")||norm(sk).equals("atletismo")))return need(r,"skill=Acrobacia|Atletismo");grantSkill(o,sk);o.put("walking_speed_bonus_m",o.optDouble("walking_speed_bonus_m",0)+1.5).put("grapple_escape_advantage",true);feature(o,"Agachamento Ágil: +1,5 m de deslocamento e vantagem em Atletismo/Acrobacia para escapar de agarrão");}
        else if(f.equals("alta magia drow")){spell(o,"Detectar Magia",-1,"long");spell(o,"Levitação",1,"long");spell(o,"Dissipar Magia",1,"long");o.put("xanathar_feat_spellcasting_ability","Carisma");}
        else if(f.equals("boa sorte")){o.put("bountiful_luck_enabled",true);feature(o,"Boa Sorte: reação quando aliado visível a 9 m rola 1 natural em ataque, teste ou salvaguarda; aliado refaz e deve usar novo resultado; seu traço Sorte fica indisponível até fim do próximo turno");}
        else if(f.equals("chamas de phlegethos")){String ab=requireAbility(c,"Inteligência|Carisma");if(ab==null)return need(r,"ability");addAbility(o,ab,1);o.put("flames_phlegethos_enabled",true);feature(o,"Chamas de Phlegethos: pode rerrolar resultados 1 nos dados de dano ígneo de magia e cria aura de fogo até fim do turno após conjurar magia de fogo");}
        else if(f.equals("constituicao infernal")){addAbility(o,"Constituição",1);token(o,"resistances","frio");token(o,"resistances","veneno");token(o,"condition_save_advantage","envenenado");}
        else if(f.equals("couro de dragao")){String ab=requireAbility(c,"Força|Constituição|Carisma");if(ab==null)return need(r,"ability");addAbility(o,ab,1);o.put("dragon_hide_natural_armor_ac",13+mod(o.optInt("dex",10)));feature(o,"Couro de Dragão: sem armadura, CA 13 + Destreza; escudo permitido; garras retráteis 1d4 + Força cortante");}
        else if(f.equals("desvanecer")){String ab=requireAbility(c,"Destreza|Inteligência");if(ab==null)return need(r,"ability");addAbility(o,ab,1);set(o,"fade_away_uses",1);feature(o,"Desvanecer: reação imediatamente após sofrer dano para ficar invisível até fim do próximo turno ou até atacar, causar dano ou forçar salvaguarda; recarga descanso curto/longo");}
        else if(f.equals("fortitude ana")){addAbility(o,"Constituição",1);o.put("dwarven_fortitude_enabled",true);feature(o,"Fortitude Anã: ao realizar Esquivar em combate, pode gastar 1 Dado de Vida e recuperar resultado + Constituição, mínimo 1");}
        else if(f.equals("furia orc")){String ab=requireAbility(c,"Força|Constituição");if(ab==null)return need(r,"ability");addAbility(o,ab,1);set(o,"orcish_fury_damage_uses",1);o.put("orcish_fury_relentless_reaction",true);feature(o,"Fúria Orc: 1/descanso curto ou longo, ao acertar arma simples/marcial some uma rolagem adicional do dado da arma; após Resistência Implacável pode usar reação para atacar com arma");}
        else if(f.equals("magia do elfo da floresta")){String cantrip=c.optString("druid_cantrip");if(cantrip.trim().isEmpty())return need(r,"druid_cantrip");o.put("wood_elf_magic_cantrip",cantrip);spell(o,cantrip,-1,"long");spell(o,"Passos Longos",1,"long");spell(o,"Passos sem Pegadas",1,"long");o.put("xanathar_feat_spellcasting_ability","Sabedoria");}
        else if(f.equals("precisao elfica")){String ab=requireAbility(c,"Destreza|Inteligência|Sabedoria|Carisma");if(ab==null)return need(r,"ability");addAbility(o,ab,1);o.put("elven_accuracy_enabled",true);feature(o,"Precisão Élfica: com vantagem em ataque usando Destreza, Inteligência, Sabedoria ou Carisma, pode rerrolar um dos dados uma vez");}
        else if(f.equals("prodigio")){String skill=c.optString("skill"),tool=c.optString("tool"),lang=c.optString("language"),expert=c.optString("expertise_skill");if(skill.trim().isEmpty()||tool.trim().isEmpty()||lang.trim().isEmpty()||expert.trim().isEmpty())return need(r,"skill|tool|language|expertise_skill");grantSkill(o,skill);token(o,"tools",tool);token(o,"languages",lang);if(!skillProficient(o,expert))return r.put("ok",false).put("reason","expertise_requires_existing_skill_proficiency");token(o,"expertise_skills",expert);feature(o,"Prodígio: proficiência em 1 perícia, 1 ferramenta, 1 idioma e especialização em perícia já proficiente");}
        else if(f.equals("segunda chance")){String ab=requireAbility(c,"Constituição|Carisma");if(ab==null)return need(r,"ability");addAbility(o,ab,1);set(o,"second_chance_uses",1);feature(o,"Segunda Chance: reação quando criatura visível acerta você; força nova rolagem; recarrega ao rolar iniciativa ou descanso curto/longo");}
        else if(f.equals("teleporte das fadas")){String ab=requireAbility(c,"Inteligência|Carisma");if(ab==null)return need(r,"ability");addAbility(o,ab,1);token(o,"languages","Silvestre");spell(o,"Passo Nebuloso",1,"short_or_long");o.put("xanathar_feat_spellcasting_ability","Inteligência");}
        else if(f.equals("temor draconico")){String ab=requireAbility(c,"Força|Constituição|Carisma");if(ab==null)return need(r,"ability");addAbility(o,ab,1);o.put("dragon_fear_enabled",true);feature(o,"Temor Dracônico: em vez de Arma de Sopro, rugido a 9 m; Sabedoria CD 8 + PB + Carisma; falha = Amedrontado por 1 minuto, repete salvaguarda após sofrer dano");}
        appendFeat(o,feat);markApplied(o,feat);o.put("xanathar_racial_feat_runtime",true);return r.put("ok",true).put("feat",feat).put("state_mutated",true);
    }catch(Exception e){try{return r.put("ok",false).put("reason","exception").put("message",String.valueOf(e.getMessage()));}catch(Exception ignored){return r;}}}

    /** Resolve uso ativo. Valores de dados sempre vêm em input; esta engine não rola. */
    public static JSONObject executeFeat(JSONObject o,String feat,JSONObject input){JSONObject r=new JSONObject();try{if(o==null||!selected(o,feat))return r.put("ok",false).put("reason","feat_not_selected");JSONObject in=input==null?new JSONObject():input;String f=norm(feat);
        if(f.equals("alta magia drow")||f.equals("magia do elfo da floresta")||f.equals("teleporte das fadas"))return cast(o,in.optString("spell"));
        if(f.equals("boa sorte")){if(!(in.optBoolean("ally_visible",false)&&in.optDouble("distance_m",999)<=9&&in.optInt("natural_d20",0)==1&&in.optBoolean("reaction_available",false)))return r.put("ok",false).put("reason","trigger_not_met");o.put("halfling_lucky_blocked_until","end_next_turn");return r.put("ok",true).put("reroll_authorized",true).put("must_use_new_result",true).put("state_mutated",true);}
        if(f.equals("chamas de phlegethos")){String mode=norm(in.optString("mode"));if(mode.equals("reroll ones")){JSONArray rolls=in.optJSONArray("rerolled_results");if(rolls==null)return need(r,"rerolled_results");return r.put("ok",true).put("must_use_rerolled_results",true).put("results",rolls);}if(mode.equals("fire spell aura")){o.put("phlegethos_aura_until","end_current_turn");return r.put("ok",true).put("bright_light_m",9).put("dim_light_extra_m",9).put("melee_attacker_fire_damage","1d4 (rolagem exigida quando ocorrer)").put("state_mutated",true);}return need(r,"mode=reroll_ones|fire_spell_aura");}
        if(f.equals("desvanecer")){if(!(in.optBoolean("just_took_damage",false)&&in.optBoolean("reaction_available",false)))return r.put("ok",false).put("reason","trigger_not_met");if(!consume(o,"fade_away_uses"))return empty(r);o.put("invisible_until","end_next_turn_or_attack_damage_save");return r.put("ok",true).put("state_mutated",true);}
        if(f.equals("fortitude ana")){if(!in.optBoolean("dodge_action",false))return r.put("ok",false).put("reason","requires_dodge_action");if(!in.has("hit_die_roll"))return need(r,"hit_die_roll");int max=Math.max(0,o.optInt("hit_dice_max",o.optInt("level",1))),spent=Math.max(0,o.optInt("hit_dice_spent",0));if(spent>=max)return r.put("ok",false).put("reason","no_hit_dice");int heal=Math.max(1,in.optInt("hit_die_roll")+mod(o.optInt("con",10)));o.put("hit_dice_spent",spent+1).put("hp",Math.min(o.optInt("max_hp",9999),o.optInt("hp",0)+heal));return r.put("ok",true).put("healing",heal).put("state_mutated",true);}
        if(f.equals("furia orc")){String mode=norm(in.optString("mode"));if(mode.equals("extra damage")){if(!in.optBoolean("weapon_hit",false)||!in.has("weapon_die_roll"))return need(r,"weapon_hit=true|weapon_die_roll");if(!consume(o,"orcish_fury_damage_uses"))return empty(r);return r.put("ok",true).put("extra_damage",Math.max(0,in.optInt("weapon_die_roll"))).put("damage_type",in.optString("damage_type","igual à arma")).put("state_mutated",true);}if(mode.equals("relentless reaction")){if(!in.optBoolean("relentless_endurance_just_used",false)||!in.optBoolean("reaction_available",false))return r.put("ok",false).put("reason","trigger_not_met");return r.put("ok",true).put("weapon_attack_authorized",true).put("reaction_cost",1);}return need(r,"mode=extra_damage|relentless_reaction");}
        if(f.equals("precisao elfica")){String ab=norm(in.optString("attack_ability"));boolean valid=ab.startsWith("des")||ab.startsWith("dex")||ab.startsWith("int")||ab.startsWith("sab")||ab.startsWith("wis")||ab.startsWith("car")||ab.startsWith("cha");return r.put("ok",in.optBoolean("has_advantage",false)&&valid).put("reroll_one_advantage_die",in.optBoolean("has_advantage",false)&&valid);}
        if(f.equals("segunda chance")){if(!(in.optBoolean("visible_attacker",false)&&in.optBoolean("hit",false)&&in.optBoolean("reaction_available",false)))return r.put("ok",false).put("reason","trigger_not_met");if(!consume(o,"second_chance_uses"))return empty(r);return r.put("ok",true).put("force_attacker_reroll",true).put("state_mutated",true);}
        if(f.equals("temor draconico")){if(!in.optBoolean("breath_weapon_available",false))return r.put("ok",false).put("reason","breath_weapon_unavailable");o.put("dragon_breath_spent",true);return r.put("ok",true).put("radius_m",9).put("save","Sabedoria").put("save_dc",8+pb(o)+mod(o.optInt("cha",10))).put("condition_on_fail","Amedrontado 1 minuto; repete salvaguarda após sofrer dano").put("state_mutated",true);}
        return r.put("ok",true).put("passive_feat",true);
    }catch(Exception e){return r;}}

    public static JSONObject shortRest(JSONObject o){try{if(o==null)return new JSONObject();if(selected(o,"Desvanecer"))reset(o,"fade_away_uses",1);if(selected(o,"Fúria Orc"))reset(o,"orcish_fury_damage_uses",1);if(selected(o,"Segunda Chance"))reset(o,"second_chance_uses",1);resetSpellRecharge(o,"short_or_long");}catch(Exception ignored){}return o;}
    public static JSONObject longRest(JSONObject o){try{if(o==null)return new JSONObject();shortRest(o);resetSpellRecharge(o,"long");o.remove("halfling_lucky_blocked_until");o.remove("phlegethos_aura_until");}catch(Exception ignored){}return o;}
    public static JSONObject onInitiative(JSONObject o){try{if(o!=null&&selected(o,"Segunda Chance"))reset(o,"second_chance_uses",1);}catch(Exception ignored){}return o;}

    private static JSONObject cast(JSONObject o,String spell)throws Exception{JSONObject r=new JSONObject();String k=norm(spell);JSONObject max=o.optJSONObject("xanathar_feat_spell_uses_max"),cur=o.optJSONObject("xanathar_feat_spell_uses_remaining");if(max==null||!max.has(k))return r.put("ok",false).put("reason","spell_not_granted");int m=max.optInt(k);if(m<0)return r.put("ok",true).put("spell",spell).put("unlimited",true);int n=cur==null?0:cur.optInt(k);if(n<=0)return r.put("ok",false).put("reason","no_free_uses_remaining");cur.put(k,n-1);o.put("xanathar_feat_spell_uses_remaining",cur);return r.put("ok",true).put("spell",spell).put("free_cast",true).put("remaining",n-1).put("state_mutated",true);}
    private static void spell(JSONObject o,String name,int uses,String recharge)throws Exception{JSONArray a=o.optJSONArray("xanathar_feat_spells");if(a==null)a=new JSONArray();boolean found=false;for(int i=0;i<a.length();i++)if(norm(a.optString(i)).equals(norm(name)))found=true;if(!found)a.put(name);o.put("xanathar_feat_spells",a);String k=norm(name);JSONObject mx=o.optJSONObject("xanathar_feat_spell_uses_max");if(mx==null)mx=new JSONObject();JSONObject cur=o.optJSONObject("xanathar_feat_spell_uses_remaining");if(cur==null)cur=new JSONObject();JSONObject rc=o.optJSONObject("xanathar_feat_spell_recharge");if(rc==null)rc=new JSONObject();mx.put(k,uses);if(!cur.has(k))cur.put(k,uses);rc.put(k,recharge);o.put("xanathar_feat_spell_uses_max",mx).put("xanathar_feat_spell_uses_remaining",cur).put("xanathar_feat_spell_recharge",rc);}
    private static void resetSpellRecharge(JSONObject o,String which)throws Exception{JSONObject mx=o.optJSONObject("xanathar_feat_spell_uses_max"),cur=o.optJSONObject("xanathar_feat_spell_uses_remaining"),rc=o.optJSONObject("xanathar_feat_spell_recharge");if(mx==null||cur==null||rc==null)return;Iterator<String> it=mx.keys();while(it.hasNext()){String k=it.next();String r=rc.optString(k);if(r.equals(which)||(which.equals("long")&&r.equals("short_or_long"))||(which.equals("short_or_long")&&r.equals("short_or_long")))cur.put(k,mx.optInt(k));}o.put("xanathar_feat_spell_uses_remaining",cur);}
    private static boolean eligible(String feat,String species,String lineage,String size){JSONArray a=eligibleFeats(species,lineage,size);for(int i=0;i<a.length();i++)if(norm(a.optString(i)).equals(norm(feat)))return true;return false;}
    private static String requireAbility(JSONObject c,String allowed){String a=c.optString("ability");String n=norm(a);for(String x:allowed.split("\\|"))if(norm(x).equals(n))return x;return null;}
    private static void addAbility(JSONObject o,String ability,int amount)throws Exception{if(o.optBoolean("xanathar_scores_include_feat_bonus",false))return;String n=norm(ability),k=n.startsWith("for")?"str":n.startsWith("des")?"dex":n.startsWith("con")?"con":n.startsWith("int")?"int_score":n.startsWith("sab")?"wis":"cha";o.put(k,Math.min(20,o.optInt(k,10)+amount));}
    private static int pb(JSONObject o){int l=Math.max(1,Math.min(20,o.optInt("level",1)));return 2+(l-1)/4;}
    private static int mod(int score){return (int)Math.floor((score-10)/2.0);}
    private static void set(JSONObject o,String k,int n)throws Exception{o.put(k,n).put(k+"_max",n);}
    private static void reset(JSONObject o,String k,int n)throws Exception{o.put(k,n).put(k+"_max",n);}
    private static boolean consume(JSONObject o,String k)throws Exception{int n=o.optInt(k,0);if(n<=0)return false;o.put(k,n-1);return true;}
    private static JSONObject empty(JSONObject r)throws Exception{return r.put("ok",false).put("reason","no_uses_remaining");}
    private static JSONObject need(JSONObject r,String x)throws Exception{return r.put("ok",false).put("reason","explicit_choice_or_roll_required").put("required",x);}
    private static boolean alreadyApplied(JSONObject o,String feat){JSONArray a=o.optJSONArray("xanathar_racial_feats_applied");if(a==null)return false;for(int i=0;i<a.length();i++)if(norm(a.optString(i)).equals(norm(feat)))return true;return false;}
    private static void markApplied(JSONObject o,String feat)throws Exception{JSONArray a=o.optJSONArray("xanathar_racial_feats_applied");if(a==null)a=new JSONArray();if(!alreadyApplied(o,feat))a.put(feat);o.put("xanathar_racial_feats_applied",a);}
    private static void appendFeat(JSONObject o,String feat)throws Exception{String raw=o.optString("selected_feats","");for(String p:raw.split("[\\n|,;•]"))if(norm(p).equals(norm(feat)))return;o.put("selected_feats",raw.trim().isEmpty()?feat:raw+"\n"+feat);feature(o,"Talento racial de Xanathar: "+feat);}
    private static boolean selected(JSONObject o,String feat){String raw=o.optString("selected_feats","");for(String p:raw.split("[\\n|,;•]"))if(norm(p).equals(norm(feat)))return true;return false;}
    private static void feature(JSONObject o,String f)throws Exception{String raw=o.optString("features","");if(!norm(raw).contains(norm(f)))o.put("features",raw+(raw.trim().isEmpty()?"":"\n")+f+".");}
    private static void token(JSONObject o,String k,String v)throws Exception{String raw=o.optString(k,"");for(String p:raw.split("[|,;•]"))if(norm(p).equals(norm(v)))return;o.put(k,raw.trim().isEmpty()?v:raw+"|"+v);}
    private static void grantSkill(JSONObject o,String skill)throws Exception{String raw=o.optString("skills","");if(!norm(raw).contains(norm(skill)))o.put("skills",raw+(raw.trim().isEmpty()?"":" • ")+skill+" ★");token(o,"feat_skill_proficiencies",skill);}
    private static boolean skillProficient(JSONObject o,String skill){String n=norm(skill);if(norm(o.optString("skills","")).contains(n))return true;return norm(o.optString("species_skill_proficiencies","")).contains(n)||norm(o.optString("background_skill_proficiencies","")).contains(n)||norm(o.optString("feat_skill_proficiencies","")).contains(n);}
    private static String baseSpecies(String species){String n=norm(species).replace(" multiverse","").trim();if(n.contains("meio elfo"))return "meio elfo";if(n.contains("meio orc"))return "meio orc";if(n.contains("duergar")||n.contains("anao"))return "anao";if(n.contains("gnomo"))return "gnomo";if(n.contains("halfling"))return "halfling";if(n.contains("draconato"))return "draconato";if(n.contains("tiefling"))return "tiefling";if(n.contains("eladrin")||n.contains("shadar kai")||n.contains("elfo"))return "elfo";if(n.equals("humano"))return "humano";return n;}
    private static String norm(String s){String x=Normalizer.normalize(s==null?"":s.toLowerCase(Locale.ROOT),Normalizer.Form.NFD).replaceAll("\\p{M}+","");return x.replaceAll("[^a-z0-9]+"," ").trim();}
}
